pdateSliderFill","syncSlider","setPreset","togItem","isOn","scheduleCalc","calculate","renderRows","renderBandTable","setPeriod","toggleBands","ensureChart","setChart","renderChart","downloadPdf","whatsappShare"],"actions":[{"line":878,"source":"function calcTax(taxableIncome) {
  let grossTax = 0;
  const bandBreakdown = [];
  for (const b of SARS_BANDS) {
    if (taxableIncome < b.from) break;
    const upper = isFinite(b.to) ? b.to : taxableIncome;
    const incomeInBand = Math.min(taxableIncome, upper) - (b.from - 1);
    const taxInBand = incomeInBand * b.rate;
    grossTax += taxInBand;
    bandBreakdown.push({
